/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import json,ast,hashlib,time
root=Path('/workspace');f=root/'proposal.json';d=json.loads(f.read_text());r=json.loads((root/'runtime.json').read_text());schema=r['study_schema']
d['study']['cost_plan']['estimate_ref']='g2-r0091-pair_summary_supplied_control wall483.1145873069763s and g2-r0091-terminal_pair_symmetric wall473.28581646084785s; frozen unit estimate481.3475877419114s, validation75.22459795698524s. Plan500s per new arm,1000s for two full units. Supplied diagnostic source is not trained; its parity gates are charged. Added content-key overhead remains unmeasured and common to both new arms.'
d['latest_knowledge_usage_review']={'source':'run://r-001 context.latest_knowledge_usage','declared_prior_use':'DIN retained; HeMix considered; original HeMix unresolved.','executed_prior_variants':['g2-r0091-pair_summary_supplied_control','g2-r0091-terminal_pair_symmetric'],'observed':'Both receipts succeeded with32192421 parameters. Symmetric click AUC lower by0.0006779516079921; candidate_diagnostics not_requested.','interpretation':'Declared source use and executed averaging are provenance. They do not confirm a mechanism or the value of an external card. The new selector addresses averaging ambiguity from this negative outcome. No claim that HeMix was implemented.'}
a=d['resource_accounting'];a['live_remaining_seconds_at_final_check']=a['unchanged_deadline_unix']-time.time();a['unallocated_safety_seconds_at_final_check']=a['live_remaining_seconds_at_final_check']-a['combined_planning_seconds']
f.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\\n')
# Validate exactly the supplied study schema, without installing a package.
def validate(obj,s,path):
 t=s.get('type')
 if t=='object':
  assert isinstance(obj,dict),(path,'type')
  assert not set(s.get('required',[]))-obj.keys(),(path,'required')
  if s.get('additionalProperties') is False:assert set(obj)<=set(s.get('properties',{})),(path,'extra')
  for k,v in obj.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 elif t=='array':
  assert isinstance(obj,list),(path,'type')
  assert len(obj)>=s.get('minItems',0),(path,'minItems')
  for i,v in enumerate(obj):validate(v,s.get('items',{}),path+str(i))
 elif t=='string':assert isinstance(obj,str) and len(obj)>=s.get('minLength',0),(path,'string')
 if 'enum' in s:assert obj in s['enum'],(path,'enum')
 if 'const' in s:assert obj==s['const'],(path,'const')
validate(d['study'],schema,'study')
assert d['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(d['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert d['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(d['variants'])<=4 and any(v['role']=='candidate' for v in d['variants'])
assert len({v['name'] for v in d['variants']})==len(d['variants'])
manifest={m['file']:m for m in d['artifact_manifest']}
for v in d['variants']+[d['diagnostic_reference']]:
 path=root/v['file'];assert path.name==v['file'] and path.suffix=='.py'
 source=path.read_text();tree=ast.parse(source);compile(source,str(path),'exec')
 assert hashlib.sha256(source.encode()).hexdigest()==manifest[v['file']]['sha256']
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config']
 assert {'check_terminal_content_selector_contract','check_terminal_content_summary_contract'}<={n.name for n in tree.body if isinstance(n,ast.FunctionDef)}
 for n in ast.walk(tree):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[a.name.split('.')[0] for a in n.names] if isinstance(n,ast.Import) else [n.module.split('.')[0]]
   assert set(names)<=set('torch numpy math typing copy functools collections itertools dataclasses contextlib unirank model_zoo'.split()),names
for file,digest in d['reproduction']['ancestor_hashes'].items():assert hashlib.sha256((root/file).read_bytes()).hexdigest()==digest
assert d['resource_accounting']['live_remaining_seconds_at_final_check']>d['resource_accounting']['combined_planning_seconds']
print('PASS supplied study schema, allowed observations/parent/protocol, two variant configs, three artifact hashes, syntax/compile, import boundary, host-gate names, unchanged ancestors, live budget fit')
print('host tensor/model/training checks: UNEXECUTED; torch unavailable')
print('proposal bytes',f.stat().st_size,'live budget safety seconds',round(a['unallocated_safety_seconds_at_final_check'],1))
PY"

